// Attend / soft join. Records an app RSVP, then opens the member event
// where the exact place and Zoom link are shown. Sign-in returns here.
// A past event stops here: no RSVP is written. ends_at when set, otherwise starts_at.
import React, { useEffect, useState } from 'react';
import { ActivityIndicator, View } from 'react-native';
import { router, useLocalSearchParams } from 'expo-router';
import { Button, EmptyState, ErrorText, Page } from '../../../components/ui';
import { applyToEvent, attendEvent, getEvent, getPublishedEvent, myEventApplication } from '../../../lib/events';
import { eventVisibility } from '../../../lib/event-visibility';
import { rememberReturnPath } from '../../../lib/auth';
import { attendanceClosed, attendanceClosedMessage, isAttendanceClosedMessage } from '../../../lib/format';
import { useSession } from '../../../lib/session';
import { colors } from '../../../lib/theme';

export default function AttendEvent() {
  const raw = useLocalSearchParams<{ id: string }>().id;
  const id = Array.isArray(raw) ? raw[0] : raw;
  const { userId, loading } = useSession();
  const [err, setErr] = useState<string | null>(null);
  const [closed, setClosed] = useState<string | null>(null);

  useEffect(() => {
    if (loading || !id) return;
    let live = true;
    (async () => {
      try {
        if (!userId) {
          const pub = await getPublishedEvent(id);
          if (!live) return;
          if (pub && attendanceClosed(pub)) {
            setClosed(attendanceClosedMessage(pub));
            return;
          }
          const next = `/events/${id}/attend`;
          rememberReturnPath(next);
          router.replace(`/sign-in?next=${encodeURIComponent(next)}`);
          return;
        }
        const event = await getEvent(id);
        if (!live) return;
        if (!event) {
          setErr('This event isn’t available.');
          return;
        }
        if (attendanceClosed(event)) {
          setClosed(attendanceClosedMessage(event));
          return;
        }
        if (eventVisibility(event.visibility) === 'hidden') {
          setErr('Use the unlisted link to RSVP.');
          return;
        }
        if (eventVisibility(event.visibility) === 'private') {
          const status = await myEventApplication(id, userId);
          if (status === 'approved') {
            await attendEvent(id, userId);
            if (live) router.replace(`/events/${id}`);
            return;
          }
          await applyToEvent(id);
          if (live) router.replace(`/e/${id}`);
          return;
        }
        await attendEvent(id, userId);
        if (live) router.replace(`/events/${id}`);
      } catch (x) {
        if (!live) return;
        const message = x && typeof x === 'object' && 'message' in x && typeof x.message === 'string'
          ? x.message
          : 'Could not attend this event.';
        if (isAttendanceClosedMessage(message)) setClosed(message);
        else setErr(message);
      }
    })();
    return () => { live = false; };
  }, [id, userId, loading]);

  if (closed && id) {
    return (
      <Page>
        <EmptyState icon="calendar-outline" title={closed}
          action={<Button small variant="neutral" title="View event" onPress={() => router.replace(userId ? `/events/${id}` : `/e/${id}`)} />} />
      </Page>
    );
  }
  if (err) return <Page><ErrorText>{err}</ErrorText></Page>;
  return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
}
